//! String formatting/printing helpers -- the Rust behind `lib/string_helpers.c`.
//!
//! Replaces: lib/string_helpers.c
//!
//! # Part of a real 3-file call cycle
//!
//! `nm -u` on the compiled objects: `vsprintf.o` calls `skip_spaces` and
//! `string_escape_mem` (both here); `cmdline_rs.o` calls `skip_spaces` (here)
//! and `simple_strtol`/`simple_strtoull` (`vsprintf.c`); this file calls
//! `get_options` (`lib/cmdline.c`, already Rust) and `kasprintf`/`snprintf`
//! (`lib/vsprintf.c`). `vsprintf.c` itself stays out of scope -- its fan-in
//! (2060 relocs) is the highest in the tree by a wide margin and needs its
//! own dedicated survey, same treatment `rbtree.c` got.
//!
//! # `lib/union_find` shape, no entry thunk
//!
//! All 19 of this file's `EXPORT_SYMBOL`s move here directly, under their own
//! names -- nothing here is called back into by another C file in a way that
//! needs a kabi-stable C body to survive.
//!
//! # `#ifdef CONFIG_FORTIFY_SOURCE` stays pristine C, unported
//!
//! `__read_overflow2_field`/`__write_overflow_field`/`__fortify_report`/
//! `__fortify_panic` are genuinely dead code in both configs this project
//! builds (`CONFIG_FORTIFY_SOURCE is not set` in both `build-fast/.config`
//! and `build-full/.config`) -- rusty-linux-e6's call, 2026-09-06: porting
//! code neither config ever builds can't clear GOALS.md's own bar (Rust must
//! be *reached in a real boot*, not just present), so it stays untouched,
//! same "can't test what neither config builds" treatment `logs/
//! build-limits.md` already gives raid6/crc-riscv/fonts.
//!
//! # `kmalloc`/`kcalloc` have no linkable symbol -- a retained C thunk
//!
//! Since 6.10's allocation profiling, `kmalloc`/`kcalloc` are
//! `alloc_hooks(..._noprof(...))` macros -- no symbol to link against. Four
//! call sites in this file allocate: `kstrdup_quotable` (caller-supplied
//! `gfp`), `kasprintf_strarray` (caller-supplied `gfp`), `parse_int_array`
//! and `kstrdup_quotable_cmdline`/`kstrdup_quotable_file` (all three hardcode
//! `GFP_KERNEL`, exactly as the C does -- `kstrdup_quotable_cmdline`/`_file`
//! ignore the `gfp` their own caller passed in for their OWN scratch
//! allocation while still forwarding it to `kstrdup_quotable()` at the end,
//! a faithful replication of the original's own inconsistency, not a bug
//! this port introduces). `GFP_KERNEL`/`PAGE_SIZE` are preprocessor/config
//! values, not symbols either, but every file using `kernel::kabi_export!`
//! already links `--extern kernel` (`scripts/Makefile.build`'s
//! `rule_rustc_o_rs`), so this file takes them straight from `kernel::
//! bindings` (the raw bindgen constants) instead of guessing at values
//! that could vary by config or arch. `kfree`/`kstrdup`/`kasprintf`/
//! `__devres_alloc_node`/`devres_add`/`devres_free` are real
//! `EXPORT_SYMBOL`s and are called directly.
//!
//! `WARN_ON()`'s bug-table entry names its own file and line; `kernel::
//! kabi_warn!` (already used by `lib/errseq_rs.rs`) gives the one call site
//! here (`kstrdup_quotable`'s self-check) that attribution directly in
//! Rust, no C thunk needed -- it takes a message where `WARN_ON()` has
//! none, which only adds context, not a behavior change.
//!
//! # `hex_asc`/`hex_to_bin`/`_ctype` are already Rust
//!
//! `lib/hexdump.c` and `lib/ctype.c` are both already fully ported
//! (thunk-free); this file `extern "C"` declares their real symbols
//! (`hex_asc`, `hex_to_bin`, `_ctype`) exactly as any other cross-file C
//! call, matching `cmdline_rs.rs`'s own `_ctype` usage.
//!
//! # `do_div()` needs nothing at all on this target
//!
//! `include/asm-generic/div64.h`: for `BITS_PER_LONG == 64` (every config
//! this project builds), `do_div(n, base)` is defined as plain
//! `remainder = n % base; n = n / base;` -- native `u64` division, no
//! 32-bit-arch remainder-and-quotient dance to replicate.
//!
//! # Variadic C calls: `kasprintf`/`snprintf`
//!
//! Declared `extern "C"` with a trailing `...`, called with fixed arguments
//! at each site -- the same pattern `hexdump_rs.rs` already established for
//! `snprintf`.
//!
//! # `ENOENT`/`ENOMEM` are hardcoded
//!
//! `2`/`12` -- stable UAPI errno values, part of the syscall ABI since
//! before this file existed, same stability class as `NUMA_NO_NODE` (`-1`)
//! below.

use core::ffi::{c_char, c_int, c_uint, c_void};
// `Flags` (`kernel::alloc::flags::GFP_KERNEL`) wraps its `u32` privately
// (`pub(crate) fn as_raw`) -- not reachable from outside the `kernel`
// crate. `kernel::bindings` is `pub use`'d, and `GFP_KERNEL`/`PAGE_SIZE`
// are plain `pub const`s there (the same bindgen output `Flags`/`page`
// wrap), so this file takes the raw values from there instead.
use kernel::bindings::{GFP_KERNEL, PAGE_SIZE};

const ENOENT: c_int = 2;
const ENOMEM: c_int = 12;
const EINVAL: c_int = 22;
/// `include/linux/numa.h`. Stable across every config/arch.
const NUMA_NO_NODE: c_int = -1;

extern "C" {
    /// `mm/slub.c`. Real `EXPORT_SYMBOL`.
    fn kfree(objp: *const c_void);
    /// `mm/util.c`. Real `EXPORT_SYMBOL`.
    fn kstrdup(s: *const c_char, gfp: c_uint) -> *mut c_char;
    /// `lib/kasprintf.c`. Real `EXPORT_SYMBOL`, variadic.
    fn kasprintf(gfp: c_uint, fmt: *const c_char, ...) -> *mut c_char;
    /// `lib/vsprintf.c`. Real `EXPORT_SYMBOL`, variadic.
    fn snprintf(buf: *mut c_char, size: usize, fmt: *const c_char, ...) -> c_int;
    /// `mm/util.c`. Real `EXPORT_SYMBOL`.
    fn memdup_user_nul(src: *const c_char, len: usize) -> *mut c_char;
    /// `fs/open.c`. Real `EXPORT_SYMBOL`. `filp` is opaque here -- this
    /// file only forwards the pointer, never dereferences it.
    fn file_path(filp: *mut c_void, buf: *mut c_char, buflen: c_int) -> *mut c_char;
    /// `mm/util.c`. Not `EXPORT_SYMBOL`, but built into the same `vmlinux`
    /// (this file is `obj-y`, never a loadable module), so an ordinary
    /// `extern "C"` link resolves it. `task` is opaque -- never dereferenced
    /// here, only forwarded.
    fn get_cmdline(task: *mut c_void, buffer: *mut c_char, buflen: c_int) -> c_int;
    /// `lib/cmdline.c`, now `lib/cmdline_rs.rs`. Validate mode (`nints ==
    /// 0`) writes the total count through `ints`, same convention this
    /// file's own `parse_int_array` relies on.
    fn get_options(str_: *const c_char, nints: c_int, ints: *mut c_int) -> *mut c_char;
    /// `drivers/base/devres.c`. Real `EXPORT_SYMBOL_GPL`. `devres_alloc()`
    /// is `#define devres_alloc(release, size, gfp) __devres_alloc_node(
    /// release, size, gfp, NUMA_NO_NODE)` -- called directly with the
    /// macro's own default node.
    fn __devres_alloc_node(
        release: unsafe extern "C" fn(*mut c_void, *mut c_void),
        size: usize,
        gfp: c_uint,
        nid: c_int,
    ) -> *mut c_void;
    /// `drivers/base/devres.c`. Real `EXPORT_SYMBOL_GPL`.
    fn devres_add(dev: *mut c_void, res: *mut c_void);
    /// `drivers/base/devres.c`. Real `EXPORT_SYMBOL_GPL`.
    fn devres_free(res: *mut c_void);
    /// `lib/hexdump.c`, now `lib/hexdump_rs.rs`. Real `EXPORT_SYMBOL`.
    static hex_asc: [u8; 16];
    /// `lib/hexdump.c`, now `lib/hexdump_rs.rs`. Real `EXPORT_SYMBOL`.
    fn hex_to_bin(ch: u8) -> c_int;
    /// `lib/ctype.c`, now `lib/ctype_rs.rs`. Real `EXPORT_SYMBOL`.
    static _ctype: [u8; 256];
    /// `lib/string.c`. Real `EXPORT_SYMBOL`.
    fn strchr(s: *const c_char, c: c_int) -> *mut c_char;
    /// `lib/string.c`. Real `EXPORT_SYMBOL`.
    fn strlen(s: *const c_char) -> usize;
    /// `lib/string.c`. Real `EXPORT_SYMBOL`.
    fn strcmp(cs: *const c_char, ct: *const c_char) -> c_int;

    /// `port/tree/lib/string_helpers.c` (retained thunk): `kmalloc(size,
    /// gfp)`. `kmalloc` has no linkable symbol since 6.10's allocation
    /// profiling.
    fn string_helpers_kmalloc(size: usize, gfp: c_uint) -> *mut c_void;
    /// `port/tree/lib/string_helpers.c`: `kcalloc(n, size, gfp)`. Same
    /// reason.
    fn string_helpers_kcalloc(n: usize, size: usize, gfp: c_uint) -> *mut c_void;
}

