// ---------------------------------------------------------------------------
// include/linux/ctype.h -- macros reading `_ctype[]`, or pure arithmetic.
// ---------------------------------------------------------------------------

const CTYPE_P: u8 = 0x10;
const CTYPE_S: u8 = 0x20;
const CTYPE_U: u8 = 0x01;
const CTYPE_L: u8 = 0x02;
const CTYPE_D: u8 = 0x04;
const CTYPE_SP: u8 = 0x80;

/// `isspace(c)`.
#[inline]
fn is_space(c: u8) -> bool {
    // SAFETY: `_ctype` is a 256-entry table indexed by a byte value.
    (unsafe { _ctype[c as usize] } & CTYPE_S) != 0
}

/// `isprint(c)`.
#[inline]
fn is_print(c: u8) -> bool {
    // SAFETY: as `is_space`.
    (unsafe { _ctype[c as usize] } & (CTYPE_P | CTYPE_U | CTYPE_L | CTYPE_D | CTYPE_SP)) != 0
}

/// `isascii(c)`.
#[inline]
fn is_ascii(c: u8) -> bool {
    c <= 0x7f
}

/// `isodigit(c)`, `include/linux/ctype.h` -- pure arithmetic, no table.
#[inline]
fn is_odigit(c: u8) -> bool {
    c.is_ascii_digit() && c < b'8'
}

/// `hex_asc_hi(x)`.
#[inline]
fn hex_asc_hi(x: u8) -> u8 {
    // SAFETY: `hex_asc` is a 16-entry table, `(x & 0xf0) >> 4` is in 0..16.
    unsafe { hex_asc[((x & 0xf0) >> 4) as usize] }
}

/// `hex_asc_lo(x)`.
#[inline]
fn hex_asc_lo(x: u8) -> u8 {
    // SAFETY: as `hex_asc_hi`.
    unsafe { hex_asc[(x & 0x0f) as usize] }
}

