/// `string_get_size(size, blk_size, units, buf, len)`,
/// `lib/string_helpers.c:39-138`.
///
/// # Safety
/// `buf` must be valid for writes for `len` bytes if `len > 0` (`snprintf`'s
/// own contract; `len <= 0` is handled by `snprintf` itself, same as the C).
#[no_mangle]
pub unsafe extern "C" fn string_get_size(
    size: u64,
    blk_size: u64,
    units: c_uint,
    buf: *mut c_char,
    len: c_int,
) -> c_int {
    // Every one of these is passed to `snprintf("%s", ...)` below, so each
    // needs its own C-style NUL terminator -- a Rust byte-string literal
    // does not carry one implicitly the way a C string literal does.
    const UNITS_10: [&[u8]; 9] = [b"\0", b"k\0", b"M\0", b"G\0", b"T\0", b"P\0", b"E\0", b"Z\0", b"Y\0"];
    const UNITS_2: [&[u8]; 9] = [b"\0", b"Ki\0", b"Mi\0", b"Gi\0", b"Ti\0", b"Pi\0", b"Ei\0", b"Zi\0", b"Yi\0"];

    let units_base = units & STRING_UNITS_MASK;
    let divisor: u64 = if units_base == STRING_UNITS_2 { 1024 } else { 1000 };

    let mut size = size;
    let mut blk_size = blk_size;
    let mut i: i32 = 0;
    let mut remainder: u32 = 0;
    let mut tmp = [0u8; 12];
    let mut tmp_used = false;

    if blk_size == 0 {
        size = 0;
    }

    if size != 0 {
        // Napier's algorithm: reduce block size to coefficient *
        // divisor^i, keeping both coefficients just under 32 bits so
        // their product doesn't overflow 64 bits.
        while (blk_size >> 32) != 0 {
            blk_size /= divisor;
            i += 1;
        }
        while (size >> 32) != 0 {
            size /= divisor;
            i += 1;
        }

        size *= blk_size;

        while size >= divisor {
            remainder = (size % divisor) as u32;
            size /= divisor;
            i += 1;
        }

        // How many digits of precision the remainder needs.
        let mut sf_cap = size as u32;
        let mut j: i32 = 0;
        while (sf_cap as u64) * 10 < 1000 {
            sf_cap = sf_cap.wrapping_mul(10);
            j += 1;
        }

        if units_base == STRING_UNITS_2 {
            // Remainder is currently out of 1024ths; express it out of
            // 1000ths instead.
            remainder = remainder.wrapping_mul(1000) >> 10;
        }

        // Round up by adding a 5 to the digit below what gets printed,
        // carrying through to `size` if that overflows a 3-digit
        // fraction.
        const ROUNDING: [u32; 3] = [500, 50, 5];
        remainder = remainder.wrapping_add(ROUNDING[j as usize]);
        if remainder >= 1000 {
            remainder -= 1000;
            size += 1;
        }

        if j != 0 {
            // SAFETY: `tmp` is a 12-byte local buffer; `snprintf` never
            // writes past `size` (its own contract) and `j+1 < 12` for
            // every `j` this loop can reach (`j <= 2`, since `ROUNDING`
            // has 3 entries and the loop above indexes it by `j`).
            unsafe {
                snprintf(
                    tmp.as_mut_ptr() as *mut c_char,
                    tmp.len(),
                    c".%03u".as_ptr(),
                    remainder,
                );
            }
            tmp[(j + 1) as usize] = 0;
            tmp_used = true;
        }
    }

    let unit: &[u8] = if (i as usize) >= UNITS_2.len() {
        b"UNK\0"
    } else if units_base == STRING_UNITS_2 {
        UNITS_2[i as usize]
    } else {
        UNITS_10[i as usize]
    };

    let no_space: &[u8] = if (units & STRING_UNITS_NO_SPACE) != 0 { b"\0" } else { b" \0" };
    let no_bytes: &[u8] = if (units & STRING_UNITS_NO_BYTES) != 0 { b"\0" } else { b"B\0" };

    let tmp_cstr: &[u8] = if tmp_used {
        let nul = tmp.iter().position(|&b| b == 0).unwrap_or(tmp.len());
        &tmp[..=nul]
    } else {
        b"\0"
    };

    // SAFETY: class B (boundary), the caller's contract -- forwarded to
    // `snprintf`, which handles `len <= 0`/truncation itself.
    unsafe {
        snprintf(
            buf,
            if len > 0 { len as usize } else { 0 },
            c"%u%s%s%s%s".as_ptr(),
            size as u32,
            tmp_cstr.as_ptr(),
            no_space.as_ptr(),
            unit.as_ptr(),
            no_bytes.as_ptr(),
        )
    }
}

