    // SAFETY: `dlen + 1` fits in a `usize` (`dlen` is bounded by
    // `string_escape_mem`'s own output, which is at most 4x `slen`, itself
    // a real string length).
    let dst = unsafe { string_helpers_kmalloc(dlen.wrapping_add(1), gfp) } as *mut c_char;
