/// `kstrdup_quotable_file(file, gfp)`, `lib/string_helpers.c:712-733`.
///
/// # Safety
/// `file`, if non-null, must be a valid pointer for `file_path()`'s own
/// contract (this file never dereferences it, only forwards it).
#[no_mangle]
pub unsafe extern "C" fn kstrdup_quotable_file(file: *mut c_void, gfp: c_uint) -> *mut c_char {
    if file.is_null() {
        // SAFETY: `b"<unknown>\0"` is a valid NUL-terminated literal.
        return unsafe { kstrdup(c"<unknown>".as_ptr(), gfp) };
    }

    // 11 spaces of headroom for " (deleted)" to be appended, same as the C.
    const PATH_MAX: usize = 4096;
    // SAFETY: `GFP_KERNEL` hardcoded, same as the C (this scratch buffer,
    // unlike the final returned string, ignores the caller's `gfp`).
    let temp = unsafe { string_helpers_kmalloc(PATH_MAX + 11, GFP_KERNEL) } as *mut c_char;
    if temp.is_null() {
        // SAFETY: as above.
        return unsafe { kstrdup(c"<no_memory>".as_ptr(), gfp) };
    }

    // SAFETY: class B (boundary), forwarded.
    let pathname = unsafe { file_path(file, temp, (PATH_MAX + 11) as c_int) };
    let result = if is_err(pathname) {
        // SAFETY: as above.
        unsafe { kstrdup(c"<too_long>".as_ptr(), gfp) }
    } else {
        // SAFETY: class B (boundary), forwarded; `pathname` points inside
        // `temp` and is NUL-terminated (`file_path`'s own contract).
        unsafe { kstrdup_quotable(pathname, gfp) }
    };

    // SAFETY: `temp` was allocated by `string_helpers_kmalloc` above.
    unsafe { kfree(temp as *const c_void) };
    result
}

