/// `kasprintf_strarray(gfp, prefix, n)`, `lib/string_helpers.c:762-781`.
///
/// # Safety
/// `prefix` must be NUL-terminated.
#[no_mangle]
pub unsafe extern "C" fn kasprintf_strarray(
    gfp: c_uint,
    prefix: *const c_char,
    n: usize,
) -> *mut *mut c_char {
    // SAFETY: `(n+1) * size_of::<*mut c_char>()` -- kcalloc
    // zero-initializes, matching the C.
    let names = unsafe {
        string_helpers_kcalloc(n.wrapping_add(1), core::mem::size_of::<*mut c_char>(), gfp)
    } as *mut *mut c_char;
    if names.is_null() {
        return core::ptr::null_mut();
    }

    let mut i: usize = 0;
    while i < n {
        // SAFETY: class B (boundary), forwarded.
        let name = unsafe { kasprintf(gfp, c"%s-%zu".as_ptr(), prefix, i) };
        if name.is_null() {
            // SAFETY: class B (boundary), forwarded; `names` holds `i`
            // initialized (non-null, by construction of this loop)
            // entries so far.
            unsafe { kfree_strarray(names, i) };
            return core::ptr::null_mut();
        }
        // SAFETY: `names` is valid for `n` writes, `i < n`.
        unsafe { *names.add(i) = name };
        i += 1;
    }

    names
}

