/// `skip_spaces(str)`, `lib/string_helpers.c:845-850`.
///
/// # Safety
/// `str` must be NUL-terminated.
#[no_mangle]
pub unsafe extern "C" fn skip_spaces(str_: *const c_char) -> *mut c_char {
    let mut p = str_;
    // SAFETY: class B (boundary), the caller's contract: NUL-terminated,
    // and `is_space(0)` is false, so this never reads past the NUL.
    while is_space(unsafe { *p as u8 }) {
        p = unsafe { p.add(1) };
    }
    p as *mut c_char
}

