/// `strim(s)`, `lib/string_helpers.c:861-877`.
///
/// # Safety
/// `s` must be NUL-terminated and valid for writes up to its own length
/// (this may write a new NUL before the existing one).
#[no_mangle]
pub unsafe extern "C" fn strim(s: *mut c_char) -> *mut c_char {
    // SAFETY: class B (boundary), the caller's contract.
    let size = unsafe { strlen(s) };
    if size == 0 {
        return s;
    }

    // SAFETY: `size - 1` is in bounds (`size != 0`, just checked).
    let mut end = unsafe { s.add(size - 1) };
    // SAFETY: `end` starts in bounds and only ever moves toward `s`,
    // guarded by the `end >= s` check each iteration.
    while end >= s && is_space(unsafe { *end as u8 }) {
        end = unsafe { end.sub(1) };
    }
    // SAFETY: `end + 1` is in bounds: either `end` is still within the
    // original string, or `end == s - 1` (the loop ran off the front),
    // and `s` itself is always a valid write target.
    unsafe { *end.add(1) = 0 };

    // SAFETY: class B (boundary), forwarded.
    unsafe { skip_spaces(s) }
}

