/// `sysfs_streq(s1, s2)`, `lib/string_helpers.c:889-904`.
///
/// # Safety
/// `s1`/`s2` must be NUL-terminated.
#[no_mangle]
pub unsafe extern "C" fn sysfs_streq(s1: *const c_char, s2: *const c_char) -> bool {
    let mut s1 = s1;
    let mut s2 = s2;
    // SAFETY: class B (boundary), the caller's contract.
    while unsafe { *s1 != 0 } && unsafe { *s1 == *s2 } {
        s1 = unsafe { s1.add(1) };
        s2 = unsafe { s2.add(1) };
    }

    // SAFETY: class B (boundary), the caller's contract.
    let (c1, c2) = unsafe { (*s1, *s2) };
    if c1 == c2 {
        return true;
    }
    // SAFETY: class B (boundary).
    if c1 == 0 && c2 == b'\n' as c_char && unsafe { *s2.add(1) } == 0 {
        return true;
    }
    // SAFETY: class B (boundary).
    if c1 == b'\n' as c_char && unsafe { *s1.add(1) } == 0 && c2 == 0 {
        return true;
    }
    false
}

