/// `memcpy_and_pad(dest, dest_len, src, count, pad)`,
/// `lib/string_helpers.c:1003-1013`.
///
/// # Safety
/// `dest` valid for writes for `dest_len` bytes; `src` valid for reads for
/// `count` bytes (or for `dest_len` bytes when `dest_len <= count`, the
/// branch actually taken in that case).
#[no_mangle]
pub unsafe extern "C" fn memcpy_and_pad(
    dest: *mut c_void,
    dest_len: usize,
    src: *const c_void,
    count: usize,
    pad: c_int,
) {
    if dest_len > count {
        // SAFETY: class B (boundary), the caller's contract.
        unsafe {
            core::ptr::copy_nonoverlapping(src as *const u8, dest as *mut u8, count);
            core::ptr::write_bytes((dest as *mut u8).add(count), pad as u8, dest_len - count);
        }
    } else {
        // SAFETY: class B (boundary), the caller's contract.
        unsafe { core::ptr::copy_nonoverlapping(src as *const u8, dest as *mut u8, dest_len) };
    }
}
